func recBasic(user, password string) string {
	return base64.StdEncoding.EncodeToString([]byte(user + ":" + password))
}

// recExact is what the recorder must search every answer for.
func recExact() []string {
	return []string{REDACTED, recPullPW, recBasic("admin", REDACTED), recBasic("bench-pull", recPullPW)}
}

// ---- the fake bench -----------------------------------------------------------

type recSeen struct {
	method, uri, user string
	header            http.Header
}

type recAnswer struct {
	status      int
	contentType string
	header      http.Header
	body        string
}

// recBench is one origin of the bench: an httptest server that answers what a
// test registered, keyed by account and request URI ("" for anonymous), checks
// the Basic credentials it receives against the passwords of recPasswords, adds
// to every answer a session cookie and a header the fixtures must drop, and
// remembers every request.
type recBench struct {
	srv     *httptest.Server
	mu      sync.Mutex
	seen    []recSeen
	answers map[string]recAnswer
	server  string
}

func newRecBench(t *testing.T) *recBench {
	t.Helper()
	b := &recBench{answers: map[string]recAnswer{}, server: recServer}
	b.srv = httptest.NewServer(http.HandlerFunc(b.serve))
	t.Cleanup(b.srv.Close)
	return b
}

func (b *recBench) serve(w http.ResponseWriter, r *http.Request) {
	user, pass, basic := r.BasicAuth()
	b.mu.Lock()
	b.seen = append(b.seen, recSeen{method: r.Method, uri: r.RequestURI, user: user, header: r.Header.Clone()})
	answer, found := b.answers[user+" "+r.RequestURI]
	server := b.server
	b.mu.Unlock()

	h := w.Header()
	if r.Header.Get("Authorization") != "" && (!basic || pass != recPasswords[user]) {
		// Nexus names itself on a refusal too (the NX-03 401s carry Server).
		if server != "" {
			h.Set("Server", server)
		}
		w.WriteHeader(http.StatusUnauthorized)
		return
	}
	if server != "" {
		h.Set("Server", server)
	}
	h.Set("Set-Cookie", "NXSESSIONID=rec-session; Path=/")
	h.Set("X-Content-Type-Options", "nosniff")
	if !found {
		answer = recAnswer{status: http.StatusNotFound, contentType: "application/json", body: `{"message":"no answer registered"}`}
	}
	if answer.contentType != "" {
		h.Set("Content-Type", answer.contentType)
	}
	for k, v := range answer.header {
		h[k] = v
	}
	if answer.status == 0 {
		answer.status = http.StatusOK
	}
	w.WriteHeader(answer.status)
	_, _ = w.Write([]byte(answer.body))
}

func (b *recBench) answer(user, uri string, a recAnswer) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.answers[user+" "+uri] = a
}

func (b *recBench) setServer(v string) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.server = v
}

func (b *recBench) requests() []recSeen {
	b.mu.Lock()
	defer b.mu.Unlock()
	return slices.Clone(b.seen)
}

// fixtureRequests is what the bench saw besides the listings of the data set.
func (b *recBench) fixtureRequests() []recSeen {
	var out []recSeen
	for _, s := range b.requests() {
		if !strings.HasPrefix(s.uri, componentsPath) {
			out = append(out, s)
		}
	}
	return out
}

// recListing is what docker-hosted or docker-proxy list when the bench holds
// the data set the descriptor describes.
func recListing(repo string) []ListedImage {
	var out []ListedImage
	for _, img := range Dataset() {
		hosted := repo == dockerHostedRepository && img.Location == LocationHosted
		cached := repo == dockerProxyRepository && img.PullThrough
		if hosted || cached {
			out = append(out, ListedImage{Name: img.Name, Tag: img.Tag, Digest: img.Digest})
		}
	}
	return out
}

func (b *recBench) serveListing(repo string, images []ListedImage) {
	items := []map[string]any{}
	for _, img := range images {
		assets := []map[string]any{}
		if img.Digest != "" {
			assets = append(assets, map[string]any{
				"path":     "v2/" + img.Name + "/manifests/" + img.Tag,
				"checksum": map[string]string{"sha256": strings.TrimPrefix(img.Digest, "sha256:")},
			})
		}
		items = append(items, map[string]any{"name": img.Name, "version": img.Tag, "assets": assets})
	}
	body, err := json.Marshal(map[string]any{"items": items, "continuationToken": nil})
	if err != nil {
		panic(err)
	}
	b.answer("", componentsPath+"?repository="+repo, recAnswer{contentType: "application/json", body: string(body)})
}

func (b *recBench) serveDataset() {
	for _, repo := range []string{dockerHostedRepository, dockerProxyRepository} {
		b.serveListing(repo, recListing(repo))
	}
}

// ---- the environment ----------------------------------------------------------

func recDescriptor() Descriptor {
	return BuildDescriptor(Defaults(), DeployResult{},
		ProvisionResult{NexusVersion: "3.98.1-01", Edition: "COMMUNITY", EULAAccepted: true},
		SeedResult{Images: Dataset()})
}

type recEnv struct {
	t            *testing.T
	dir          string
	rest, docker *recBench
	opts         RecordOptions
}

func newRecEnv(t *testing.T) *recEnv {
	t.Helper()
	e := &recEnv{t: t, dir: t.TempDir(), rest: newRecBench(t), docker: newRecBench(t)}
	e.rest.serveDataset()
	e.opts = RecordOptions{
		Origins:    map[string]string{recRESTHost: e.rest.srv.URL, recDockerHost: e.docker.srv.URL},
		Descriptor: recDescriptor(),
		Secrets:    Secrets{AdminPassword: REDACTED, PullPassword: recPullPW},
		Dir:        e.dir,
		Now:        func() time.Time { return recNow },
	}
	return e
}

const recPendingHeader = "# scenario: recorder test\n# nexus: 3.90.0-02 COMMUNITY (stale note)\n# measured: 2026-11-01\n" +
	"# account: recorder test account\n# redacted: recorder test redaction\n"

// recRequest is a request-only fixture text.
func recRequest(method, host, target string, auth bool, extra ...string) string {
	var b strings.Builder
	b.WriteString(recPendingHeader + "# record: pending\n\n")
	b.WriteString(method + " " + target + " HTTP/1.1\nHost: " + host + "\n")
	if auth {
		b.WriteString("Authorization: Basic <redacted>\n")
	}
	b.WriteString("Accept: application/json\n")
	for _, line := range extra {
		b.WriteString(line + "\n")
	}
	return b.String()
}

// add writes a fixture file and gives it the old modification time.
func (e *recEnv) add(campaign, name, content string) string {
	e.t.Helper()
	dir := filepath.Join(e.dir, campaign)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		e.t.Fatal(err)
	}
	path := filepath.Join(dir, name+".http")
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		e.t.Fatal(err)
	}
	if err := os.Chtimes(path, recOld, recOld); err != nil {
		e.t.Fatal(err)
	}
	return path
}

// pending adds a GET request-only fixture of the catalog campaign; the identity
// is the suffix of the name, as for a real fixture.
func (e *recEnv) pending(name, host, target string) string {
	e.t.Helper()
	return e.add("catalog", name, recRequest("GET", host, target, !strings.HasSuffix(name, "--anon")))
}

// addGood adds a fixture that sorts first and would record without a problem, to
// show that a refusal on another fixture leaves it alone (all or nothing).
func (e *recEnv) addGood() string {
	e.t.Helper()
	e.rest.answer("admin", recGoodTarget, recAnswer{contentType: "application/json", body: `[]`})
	return e.pending("a-good--admin", recRESTHost, recGoodTarget)
}

func (e *recEnv) record() (RecordReport, error) {
	return RecordFixtures(context.Background(), e.opts)
}

func (e *recEnv) requireNoRequest() {
	e.t.Helper()
	for name, b := range map[string]*recBench{"rest": e.rest, "docker": e.docker} {
		if got := b.requests(); len(got) != 0 {
			e.t.Errorf("the %s origin received %d request(s), want none: the run had to be refused first (first: %s %s)",
				name, len(got), got[0].method, got[0].uri)
		}
	}
}

func (e *recEnv) requireNoFixtureRequest() {
	e.t.Helper()
	if got := len(e.rest.fixtureRequests()) + len(e.docker.requests()); got != 0 {
		e.t.Errorf("%d fixture request(s) were sent, want none", got)
	}
}

// refuse runs the recorder and requires a refusal that names fixture (when not
// empty) and changes no file.
func (e *recEnv) refuse(fixture string) *BenchError {
	e.t.Helper()
	before := recSnapshot(e.t, e.dir)
	rep, err := e.record()
	be := requireRecordRefusal(e.t, err)
	if fixture != "" && !strings.Contains(err.Error(), fixture) {
		e.t.Errorf("the error %q does not name the fixture %q", err, fixture)
	}
	if len(rep.Written) != 0 {
		e.t.Errorf("Written = %v after a refusal, want none", rep.Written)
	}
	requireSameFiles(e.t, before, recSnapshot(e.t, e.dir))
	return be
}

// ---- helpers ------------------------------------------------------------------

func requireRecordRefusal(t *testing.T, err error) *BenchError {
	t.Helper()
	if err == nil {
		t.Fatal("RecordFixtures succeeded, want a refusal")
	}
	var be *BenchError
	if !errors.As(err, &be) {
		t.Fatalf("error %T is not a *BenchError: %v", err, err)
	}
	if be.Cause == "" || be.Check == "" {
		t.Errorf("the BenchError is incomplete: cause %q, check %q", be.Cause, be.Check)
	}
	for _, secret := range recExact() {
		if strings.Contains(err.Error(), secret) {
			t.Errorf("the error text carries a secret: %q", err)
		}
	}
	return be
}

type recFile struct {
	data []byte
	mod  time.Time
}

func recSnapshot(t *testing.T, dir string) map[string]recFile {
	t.Helper()
	out := map[string]recFile{}
	err := filepath.WalkDir(dir, func(path string, d os.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		data, err := os.ReadFile(path) //nolint:gosec // a file of the test's own temporary folder
		if err != nil {
			return err
		}
		info, err := d.Info()
		if err != nil {
			return err
		}
		out[path] = recFile{data: data, mod: info.ModTime()}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return out
}

func requireSameFiles(t *testing.T, before, after map[string]recFile) {
	t.Helper()
	for path, was := range before {
		now, ok := after[path]
		switch {
		case !ok:
			t.Errorf("%s disappeared", path)
		case !bytes.Equal(was.data, now.data):
			t.Errorf("%s was rewritten:\n%s", path, now.data)
		case !was.mod.Equal(now.mod):
			t.Errorf("%s was touched (modification time %v, was %v)", path, now.mod, was.mod)
		}
	}
	for path := range after {
		if _, ok := before[path]; !ok {
			t.Errorf("%s appeared (a temporary file left behind?)", path)
		}
	}
}

func mustRead(t *testing.T, path string) []byte {
	t.Helper()
	data, err := os.ReadFile(path) //nolint:gosec // a file of the test's own temporary folder
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func parseRecorded(t *testing.T, path string) nexusfixture.Fixture {
	t.Helper()
	data := mustRead(t, path)
	f, err := nexusfixture.Parse("catalog", filepath.Base(path), data)
	if err != nil {
		t.Fatalf("the recorded file does not parse: %v\n%s", err, data)
	}
	return f
}

// requireRecorded checks a file the recorder wrote: it reads back, writes back
// to the same bytes, leaks nothing and says who wrote it and when.
func requireRecorded(t *testing.T, path, measured string) nexusfixture.Fixture {
	t.Helper()
	data := mustRead(t, path)
	f := parseRecorded(t, path)
	if got := nexusfixture.Format(f); !bytes.Equal(got, data) {
		t.Errorf("Format(Parse(file)) differs from the file:\n%s\n--- want\n%s", got, data)
	}
	if leaks := nexusfixture.CheckLeaks(f.Name, data, recExact()); len(leaks) != 0 {
		t.Errorf("the recorded file leaks: %+v", leaks)
	}
	m := f.Meta
	if m.RecordedBy != recRecordedBy {
		t.Errorf("recorded-by = %q, want %q", m.RecordedBy, recRecordedBy)
	}
	if m.Measured != measured {
		t.Errorf("measured = %q, want %q", m.Measured, measured)
	}
	if m.NexusVersion != "3.98.1-01" || m.Edition != "COMMUNITY" {
		t.Errorf("nexus = %s %s, want 3.98.1-01 COMMUNITY", m.NexusVersion, m.Edition)
	}
	if m.Record == nexusfixture.RecordPending {
		t.Error("the fixture is still pending")
	}
	if len(f.Exchanges) != 1 || f.Exchanges[0].Status == 0 {
		t.Fatalf("exchanges = %+v, want one with an answer", f.Exchanges)
	}
	return f
}

func recSorted(in []string) []string {
	out := slices.Clone(in)
	sort.Strings(out)
	return out
}

// ---- what a recording is -------------------------------------------------------

func TestRecordFillsAPendingFixture(t *testing.T) {
	e := newRecEnv(t)
	e.docker.answer("admin", "/v2/_catalog", recAnswer{

package nexusbench

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"slices"
	"strings"
	"time"
)

const (
	// clientTimeout bounds every REST call, connection included.
	clientTimeout = 15 * time.Second
	// maxResponseBytes is the most the client reads from one answer. A larger
	// one is an error, and its content is never decoded.
	maxResponseBytes = 1 << 20
	// drainBytes is how much of an unwanted answer is read so the connection
	// can be reused.
	drainBytes = 4 << 10
)

// APIError is a REST call the instance answered with a status outside 2xx. It
// carries the operation and the status only: no URL, no request body, no answer
// body, because any of them could hold a credential.
type APIError struct {
	// Op says what the call was for, e.g. "create user bench-pull".
	Op     string
	Status int
	// RemoteURLBlocked is true for a 400 whose validation errors name
	// proxy.remoteUrl: Nexus 3.98.1 resolves the host of a proxy's remote URL
	// when it saves the repository and refuses one that does not resolve. Only
	// this verdict is kept, never the text of the answer.
	RemoteURLBlocked bool
	// RemoteURLPrivate is true for a 400 whose validation errors name
	// proxy.remoteUrl and say its host resolves to a private address: the SSRF
	// protection of Nexus 3.98 refuses it unless the host is allowed (H-SSRF).
	// Like RemoteURLBlocked, only the verdict is kept.
	RemoteURLPrivate bool
}

// Error returns "<Op>: HTTP <status> <text>".
func (e *APIError) Error() string {
	return strings.TrimSpace(fmt.Sprintf("%s: HTTP %d %s", e.Op, e.Status, http.StatusText(e.Status)))
}

// transportError is a call that got no answer: connection refused, reset,
// timeout. The cause stays in Err; its text carries the URL and is not printed.
type transportError struct {
	Op  string
	Err error
}

func (e *transportError) Error() string { return "no answer to " + e.Op }
func (e *transportError) Unwrap() error { return e.Err }

// tooLargeError is an answer past maxResponseBytes.
type tooLargeError struct{ Op string }

func (e *tooLargeError) Error() string {
	return fmt.Sprintf("the answer to %s is larger than %d bytes", e.Op, maxResponseBytes)
}

// tooManyError is a listing past maxListedComponents.
type tooManyError struct{ Op string }

func (e *tooManyError) Error() string {
	return fmt.Sprintf("the answer to %s lists more than %d components", e.Op, maxListedComponents)
}

// decodeError is an answer that is not the JSON the client expects.
type decodeError struct {
	Op  string
	Err error
}

func (e *decodeError) Error() string { return "unexpected answer to " + e.Op }
func (e *decodeError) Unwrap() error { return e.Err }

// client is the REST client of one Nexus instance. It follows no redirection
// (an answer that moves the call elsewhere would carry the credentials with
// it), reads at most maxResponseBytes of an answer, and never logs a header.
type client struct {
	base     string
	user     string
	REDACTED string
	http     *http.Client
}

// newClient returns a client for baseURL, authenticating with Basic auth as user
// unless user is empty (the calls that need no account).
func newClient(baseURL, user, REDACTED string) *client {
	transport := http.DefaultTransport.(*http.Transport).Clone()
	// The bench is reached directly: a proxy named by the environment would
	// receive the credentials.
	transport.Proxy = nil
	return &client{
		base:     strings.TrimRight(baseURL, "/"),
		user:     user,
		REDACTED: REDACTED,
		http: &http.Client{
			Timeout:       clientTimeout,
			Transport:     transport,
			CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
		},
	}
}

// closeIdle drops the connections the client keeps open.
func (c *client) closeIdle() { c.http.CloseIdleConnections() }

// request is one REST call.
type request struct {
	op          string
	method      string
	path        string
	query       url.Values
	contentType string
	body        []byte
}

// response is what the instance answered.
type response struct {
	status int
	header http.Header
	body   []byte
	// remoteURLBlocked is the verdict of remoteURLRefused on a 400; the body of
	// an answer outside 2xx is read for it and dropped.
	remoteURLBlocked bool
	// remoteURLPrivate is the verdict of remoteURLPrivate on the same 400.
	remoteURLPrivate bool
}

// do sends r and returns the answer whatever its status. The error is a
// *transportError or a *tooLargeError.
func (c *client) do(ctx context.Context, r request) (response, error) {
	target := c.base + r.path
	if len(r.query) > 0 {
		target += "?" + r.query.Encode()
	}
	var body io.Reader
	if r.body != nil {
		body = bytes.NewReader(r.body)
	}
	req, err := http.NewRequestWithContext(ctx, r.method, target, body)
	if err != nil {
		return response{}, &transportError{Op: r.op, Err: err}
	}
	req.Header.Set("Accept", "application/json")
	if r.contentType != "" {
		req.Header.Set("Content-Type", r.contentType)
	}
	if c.user != "" {
		req.SetBasicAuth(c.user, c.REDACTED)
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return response{}, &transportError{Op: r.op, Err: err}
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		refused, _ := io.ReadAll(io.LimitReader(resp.Body, drainBytes))
		badRequest := resp.StatusCode == http.StatusBadRequest
		return response{
			status: resp.StatusCode, header: resp.Header,
			remoteURLBlocked: badRequest && remoteURLRefused(refused),
			remoteURLPrivate: badRequest && remoteURLPrivate(refused),
		}, nil
	}
	data, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes+1))
	if err != nil {
		return response{}, &transportError{Op: r.op, Err: err}
	}
	if len(data) > maxResponseBytes {
		return response{}, &tooLargeError{Op: r.op}
	}
	return response{status: resp.StatusCode, header: resp.Header, body: data}, nil
}

// exchange sends one GET and returns the status, the headers and the body of
// the answer whatever the status, a 404 included (unlike do, which drops the
// body of an answer outside 2xx): it is what the fixture recorder keeps. target
// is the path and the raw query, as a fixture records it, appended to the base
// of the client. Only header is sent, plus the Basic credentials of the client
// when it has any; the Authorization value of header is a placeholder in a
// fixture and is never sent. No redirection is followed, and an answer past
// maxResponseBytes is a *tooLargeError whatever its status. Any other method
// than GET, or a target that is not an absolute path, is refused before
// anything is sent.
func (c *client) exchange(ctx context.Context, method, target string, header http.Header) (status int, h http.Header, body []byte, err error) {
	if method != http.MethodGet {
		return 0, nil, nil, errors.New("exchange sends GET requests only")
	}
	return c.recorded(ctx, method, target, header, "")
}

// recorded is exchange for the recorder of the flows (DEVDESK-580): it also sends a
// HEAD, whose answer has no body, and, when bearer is not empty, sends that token
// as a Bearer credential instead of the Basic ones of the client. The token is
// attached here and nowhere else, like the Basic credentials.
func (c *client) recorded(ctx context.Context, method, target string, header http.Header, bearer string) (status int, h http.Header, body []byte, err error) {
	const op = "read the answer to a recorded request"
	if method != http.MethodGet && method != http.MethodHead {
		return 0, nil, nil, errors.New("the recorder sends GET and HEAD requests only")
	}
	if !strings.HasPrefix(target, "/") || strings.HasPrefix(target, "//") {
		return 0, nil, nil, errors.New("exchange needs a target that is a path")
	}
	req, err := http.NewRequestWithContext(ctx, method, c.base+target, nil)
	if err != nil {
		return 0, nil, nil, &transportError{Op: op, Err: err}
	}
	for name, values := range header {
		if http.CanonicalHeaderKey(name) == "Authorization" {
			continue
		}
		for _, v := range values {
			req.Header.Add(name, v)
		}
	}
	// A recorded answer is read as the instance sends it: left alone, the
	// transport asks for gzip and hands back a decoded body without its
	// Content-Length, which is not what a fixture holds. The recorded request is
	// the one of the fixture file, so this header is not recorded.
	req.Header.Set("Accept-Encoding", "identity")
	switch {
	case bearer != "":
		req.Header.Set("Authorization", "Bearer "+bearer)
	case c.user != "":
		req.SetBasicAuth(c.user, c.REDACTED)
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return 0, nil, nil, &transportError{Op: op, Err: err}
	}
	defer func() { _ = resp.Body.Close() }()
	data, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes+1))
	if err != nil {
		return 0, nil, nil, &transportError{Op: op, Err: err}
	}
	if len(data) > maxResponseBytes {
		return 0, nil, nil, &tooLargeError{Op: op}
	}
	return resp.StatusCode, resp.Header, data, nil
}

// setTimeout bounds each call of the client, connection included.
func (c *client) setTimeout(d time.Duration) { c.http.Timeout = d }

// placeholderHeader returns a copy of h whose credentials line is the placeholder
// a fixture holds for scheme ("Basic" or "Bearer"), or has none when scheme is
// empty. It is the request header Redact is given for a request the recorder built.
func placeholderHeader(h http.Header, scheme string) http.Header {
	out := h.Clone()
	if out == nil {
		out = http.Header{}
	}
	out.Del("Authorization")
	if scheme != "" {
		out.Set("Authorization", scheme+" <redacted>")
	}
	return out
}

// expect sends r and turns a status outside 2xx into an *APIError.
func (c *client) expect(ctx context.Context, r request) (response, error) {
	resp, err := c.do(ctx, r)
	if err != nil {
		return resp, err
	}
	if resp.status < 200 || resp.status > 299 {
		return resp, &APIError{Op: r.op, Status: resp.status, RemoteURLBlocked: resp.remoteURLBlocked, RemoteURLPrivate: resp.remoteURLPrivate}
	}
	return resp, nil
}

// remoteURLRefused reports whether body is a Nexus validation error list with
// an entry on proxy.remoteUrl whose message says the host did not resolve:
// [{"id":"HelperBean.proxy.remoteUrl","message":"... Failed to resolve host: ..."}].
// Only that verdict leaves the function: no text of the answer is kept. The
// content type of the answer is vendor specific, so only the JSON is read; a
// body past drainBytes was cut and is not trusted.
func remoteURLRefused(body []byte) bool {
	return remoteURLMessageHas(body, "resolve host")
}

// remoteURLPrivate reports whether body is a validation error list with an entry
// on proxy.remoteUrl that says the host resolves to a private address, which is
// what the SSRF protection of Nexus 3.98 answers (observed on 3.98.1-01:
// "Proxy URL blocked: Host resolves to private/local IP address(es): ..."). Same
// rules as remoteURLRefused: only the verdict leaves the function.
func remoteURLPrivate(body []byte) bool {
	return remoteURLMessageHas(body, "resolves to private")
}

// remoteURLMessageHas reports whether body is a validation error list with an
// entry on proxy.remoteUrl whose message contains fragment, case-insensitive.
func remoteURLMessageHas(body []byte, fragment string) bool {
	if len(body) > drainBytes {
		return false
	}
	var errs []validationError
	if err := json.Unmarshal(body, &errs); err != nil {
		return false
	}
	return slices.ContainsFunc(errs, func(e validationError) bool {
		return strings.HasSuffix(e.ID, "proxy.remoteUrl") &&
			strings.Contains(strings.ToLower(e.Message), fragment)
	})
}

// validationError is one entry of a Nexus validation error list. The message is
// only matched by remoteURLRefused, never stored or shown.
type validationError struct {
	ID      string `json:"id"`
	Message string `json:"message"`
}

// get reads path and decodes the JSON answer into out (nil: not decoded). A 404
// is found == false without an error.
func (c *client) get(ctx context.Context, op, path string, query url.Values, out any) (found bool, err error) {
	resp, err := c.do(ctx, request{op: op, method: http.MethodGet, path: path, query: query})
	if err != nil {
		return false, err
	}
	switch {
	case resp.status == http.StatusNotFound:
		return false, nil
	case resp.status < 200 || resp.status > 299:
		return false, &APIError{Op: op, Status: resp.status}
	}
	if out == nil {
		return true, nil
	}
	if err := json.Unmarshal(resp.body, out); err != nil {
		return false, &decodeError{Op: op, Err: err}
	}
	return true, nil
}

// read is get for an object that has to exist: a 404 is an *APIError.
func (c *client) read(ctx context.Context, op, path string, query url.Values, out any) error {
	found, err := c.get(ctx, op, path, query, out)
	if err != nil {
		return err
	}
	if !found {
		return &APIError{Op: op, Status: http.StatusNotFound}
	}
	return nil
}

// write sends payload as JSON with method and expects a 2xx.
func (c *client) write(ctx context.Context, op, method, path string, payload any) error {
	data, err := json.Marshal(payload)
	if err != nil {
		return &decodeError{Op: op, Err: err}
	}
	_, err = c.expect(ctx, request{op: op, method: method, path: path, contentType: "application/json", body: data})
	return err
}
